{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Compassionate, evidence-informed therapy in {{CITY}}, {{STATE}}. Individual sessions, short cohorts, and focused planning with clear boundaries and confidentiality." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="page-root">
  <header class="site-header">
    <div class="wrapper nav-row">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="primary-nav" aria-label="Main navigation">
        <a href="about.html">Meet</a>
        <a href="specialties.html">Ways I Help</a>
        <a href="approach.html">How I Work</a>
        <a href="fees.html">Investment</a>
        <a href="faq.html">Questions</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button class="nav-toggle" aria-label="Open menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero">
      <div class="pattern"></div>
      <div class="wrapper hero-inner">
        <div class="hero-text">
          <h1>Care that meets you where you are, with steady clinical guidance.</h1>
          <p class="lead">Work with a clinician who values clarity, privacy, and practical movement — one step at a time.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="about.html">Meet me</a>
          </div>
          <p class="contact-inline">Call: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
        <div class="hero-card">
          <div class="card-inner">
            <h3>New cohort starting soon</h3>
            <p class="muted">Small group program for steady peer-informed growth (limited seats for group integrity; no pressure to join).</p>
            <a class="btn" href="book.html">See cohort details</a>
          </div>
        </div>
      </div>
    </section>

    <!-- STORY -->
    <section id="story" class="story wrapper">
      <div class="story-grid">
        <div>
          <h2>Quietly rigorous care</h2>
          <p>I blend evidence-informed approaches with practical planning so you can make decisions that last. Sessions are collaborative: you bring the context, I bring the clinical focus. Together we set goals that fit your life, not the other way around.</p>
        </div>
        <div>
          <h3>Who I work with</h3>
          <ul>
            <li>Adults navigating transitions (career, relationships, identity)</li>
            <li>People managing persistent anxiety or low mood</li>
            <li>Those seeking short-term focused work or supportive ongoing care</li>
          </ul>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK -->
    <section id="framework" class="framework">
      <div class="wrapper">
        <h2>My working map</h2>
        <p class="muted">A practical roadmap we use together to mark progress and revisit direction.</p>
        <div class="steps">
          <div class="step">
            <div class="num">1</div>
            <h4>Listen & map</h4>
            <p>We create a focused picture of what's most important now.</p>
          </div>
          <div class="step">
            <div class="num">2</div>
            <h4>Clarify aims</h4>
            <p>Identify small, measurable goals that respect your context.</p>
          </div>
          <div class="step">
            <div class="num">3</div>
            <h4>Practice & adjust</h4>
            <p>Try strategies between sessions, revisit and adapt as needed.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- OFFERS / PROGRAMS (Cohort model highlighted) -->
    <section id="offers" class="offers wrapper">
      <h2>Offerings</h2>
      <p class="muted">Individual work, short cohorts, and focused intensives designed with clear boundaries and confidentiality.</p>
      <div class="offer-grid">
        <div class="offer">
          <h3>Individual Sessions</h3>
          <p>One-on-one sessions, scheduled weekly or biweekly. Flexible pacing, focused agenda-setting each meeting.</p>
          <a class="btn" href="fees.html">See fees</a>
        </div>
        <div class="offer">
          <h3>Small Cohort</h3>
          <p>6-week cohort for focused skill-building and mutual support. Cohorts are closed groups to preserve continuity and confidentiality.</p>
          <a class="btn" href="book.html">Join cohort info session</a>
        </div>
        <div class="offer">
          <h3>Focused Planning Intensive</h3>
          <p>A short block of sessions for decision-making and planning during a transition. Time-limited, practical focus.</p>
          <a class="btn" href="book.html">Learn more</a>
        </div>
      </div>
    </section>

    <!-- PRICING (framed uniquely) -->
    <section id="pricing" class="pricing wrapper">
      <h2>Investment</h2>
      <p class="muted">Pricing is transparent and intended to fit different levels of intensity and commitment.</p>
      <div class="pricing-grid">
        <div class="price-card">
          <h4>Starter Rhythm</h4>
          <p class="price">Per session</p>
          <p class="muted">For occasional check-ins and short-term focus.</p>
        </div>
        <div class="price-card featured">
          <h4>Steady Rhythm</h4>
          <p class="price">Monthly plan</p>
          <p class="muted">Best for ongoing work with room to adjust pacing.</p>
        </div>
        <div class="price-card">
          <h4>Cohort Tuition</h4>
          <p class="price">Program rate</p>
          <p class="muted">Includes group sessions and materials; limited seats support group cohesion.</p>
        </div>
      </div>
      <p class="note">Insurance: I can provide superbills for out-of-network reimbursement. Please contact for details.</p>
    </section>

    <!-- TESTIMONIALS + PROOF GALLERY (rotating) -->
    <section id="testimonials" class="testimonials wrapper">
      <h2>What people say</h2>
      <div class="proof-gallery" aria-live="polite">
        <div class="testi-viewport">
          <blockquote class="testi active" data-id="1">“I finally felt seen and understood, and we focused on what actually helped me move forward.”<cite>— J., 34</cite></blockquote>
          <blockquote class="testi" data-id="2">“The cohort gave me new tools and a sense of direction without feeling pressured.”<cite>— A., 29</cite></blockquote>
          <blockquote class="testi" data-id="3">“Sessions were practical and compassionate — a good balance.”<cite>— M., 42</cite></blockquote>
        </div>
        <div class="badges" role="list">
          <div class="badge" data-tip="Licensed clinician; continuing education">LIC: MA, LMFT</div>
          <div class="badge" data-tip="Trauma-informed practices">Trauma-Informed</div>
          <div class="badge" data-tip="Group facilitation training">Group Cohort Leader</div>
        </div>
        <div class="controls">
          <button id="prev">‹</button>
          <button id="next">›</button>
        </div>
      </div>
    </section>

    <!-- SESSION BOUNDARIES & CONFIDENTIALITY ACCORDION -->
    <section id="boundaries" class="boundaries wrapper">
      <h2>Session boundaries, confidentiality, and scope</h2>
      <div class="accordion">
        <button class="acc-head" aria-expanded="false">Confidentiality & records</button>
        <div class="acc-body">
          <p>Conversations are held in confidence consistent with applicable law. Records are kept securely and shared only with consent, except where law requires disclosure (e.g., imminent risk, court order). I will discuss limits to confidentiality at intake and answer any questions you have.</p>
        </div>

        <button class="acc-head" aria-expanded="false">Payment & cancellations</button>
        <div class="acc-body">
          <p>Payment is due at the time of service. Cancellation policies are shared at intake and in the intake packet. I strive for clarity around scheduling and billing.</p>
        </div>

        <button class="acc-head" aria-expanded="false">Scope of care</button>
        <div class="acc-body">
          <p>I provide psychotherapy and coaching within my scope of training. I do not provide emergency services or clinical supervision here — if you need crisis support I will help connect you with appropriate resources.</p>
        </div>
      </div>
      <div class="crisis-note">
        <strong>If you are in immediate danger or are having thoughts of harming yourself or others:</strong>
        <p>Please call your local emergency number, or contact crisis services. In the U.S., you can call or text 988 to reach the Suicide & Crisis Lifeline. If you are outside the U.S., please contact local emergency services or your local crisis resources.</p>
      </div>
    </section>

    <!-- CTA -->
    <section class="final-cta wrapper">
      <h2>Ready to begin?</h2>
      <p class="muted">Reach out for a brief consult to see if we're a good fit.</p>
      <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <p class="small">Or call <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrapper footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <address>{{CITY}}, {{STATE}}<br><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></address>
      </div>
      <div>
        <nav>
          <a href="about.html">Meet</a>
          <a href="book.html">Book</a>
          <a href="contact.html">Reach out</a>
        </nav>
      </div>
      <div class="mini-proof" aria-live="polite">
        <div class="mini-quote">“Helpful, practical, and attentive.” — K.</div>
      </div>
    </div>
    <p class="copyright">&copy; <span id="year"></span> {{BUSINESS_NAME}}. Licensed clinician. All clinical care respects confidentiality and scope.</p>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
