{"path":"assets/css/styles.css","content":"/* Core styles for bold_playful layout — no external assets used */
:root{
  --bg:#fff;--card:#fff;--accent:#ff6b6b;--accent-2:#3b82f6;--muted:#6b7280;--dark:#0f172a;--radius:12px;
  --maxw:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;color:var(--dark);background:linear-gradient(180deg,#fbfbff 0%,#fff 100%);}
.wrapper{max-width:var(--maxw);margin:0 auto;padding:2rem}
.site-header{border-bottom:1px solid #eef2ff;background:linear-gradient(90deg,rgba(59,130,246,0.02),transparent)}
.nav-row{display:flex;align-items:center;justify-content:space-between;padding:1rem 0}
.brand{font-weight:700;color:var(--dark);text-decoration:none;font-size:1.1rem}
.primary-nav a{margin-left:1rem;color:var(--dark);text-decoration:none}
.primary-nav .cta{background:var(--accent);color:#fff;padding:.5rem .8rem;border-radius:8px}
.nav-toggle{display:none;background:none;border:1px solid #e6eefc;padding:.4rem .6rem;border-radius:8px}

.hero{position:relative;padding:3rem 0;background:linear-gradient(180deg,#fff 0%,#f7fbff 100%)}
.hero .pattern{position:absolute;right:0;top:0;bottom:0;width:40%;background-image:url('assets/img/pattern.svg');background-repeat:no-repeat;background-size:cover;opacity:.12}
.hero-inner{display:grid;grid-template-columns:1fr 360px;gap:2rem;align-items:center}
.hero-text h1{font-size:clamp(1.4rem,3.4vw,2.2rem);margin:0 0 .6rem}
.lead{color:var(--muted);margin-bottom:1rem}
.btn{display:inline-block;padding:.6rem .9rem;border-radius:10px;text-decoration:none;border:1px solid transparent}
.btn.primary{background:var(--accent-2);color:#fff}
.btn.ghost{background:transparent;border:1px solid #dbeafe;color:var(--dark)}
.btn.large{padding:1rem 1.2rem;font-size:1.05rem}
.hero-card{background:linear-gradient(180deg,#fff,#fbfbff);border-radius:12px;box-shadow:0 6px 20px rgba(2,6,23,0.06);padding:1rem}
.card-inner h3{margin:.2rem 0}
.card-inner .muted{color:var(--muted);font-size:.95rem}
.contact-inline{margin-top:.8rem;color:var(--muted)}

.story{padding:2rem 0}
.story-grid{display:grid;grid-template-columns:1fr 300px;gap:1.5rem}

.framework{background:#fffefb;padding:2rem 0}
.steps{display:flex;gap:1rem;margin-top:1rem}
.step{background:#fff;border-radius:12px;padding:1rem;flex:1}
.num{background:var(--accent);color:#fff;width:34px;height:34px;border-radius:9px;display:inline-grid;place-items:center;font-weight:700;margin-bottom:.5rem}

.offers{padding:2rem 0}
.offer-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}
.offer{background:#fff;border-radius:12px;padding:1rem;box-shadow:0 6px 18px rgba(2,6,23,0.04)}

.pricing{padding:2rem 0}
.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}
.price-card{background:#fff;border-radius:12px;padding:1rem;text-align:center}
.price-card.featured{border:2px solid var(--accent-2)}
.note{color:var(--muted);margin-top:.6rem}

.testimonials{padding:2rem 0}
.proof-gallery{display:grid;grid-template-columns:1fr 200px;gap:1rem;align-items:center}
.testi-viewport{min-height:120px;position:relative}
.testi{position:absolute;left:0;right:0;opacity:0;transform:translateY(6px);transition:all .35s ease;color:var(--dark);background:#fff;padding:1rem;border-radius:10px;box-shadow:0 8px 22px rgba(2,6,23,0.06)}
.testi.active{opacity:1;transform:none}
.testi cite{display:block;margin-top:.6rem;color:var(--muted);font-style:normal}
.badges{display:flex;flex-direction:column;gap:.5rem}
.badge{background:#fff;border:1px solid #eef2ff;padding:.5rem;height:46px;border-radius:8px;display:flex;align-items:center;justify-content:center;cursor:pointer}
.controls{display:flex;gap:.5rem}
.controls button{background:#fff;border:1px solid #eef2ff;padding:.4rem .6rem;border-radius:8px}

.boundaries{padding:2rem 0}
.accordion{border-radius:12px;background:#fff;padding:1rem;box-shadow:0 6px 18px rgba(2,6,23,0.04)}
.acc-head{width:100%;text-align:left;padding:.8rem;border:none;background:transparent;font-weight:600;border-bottom:1px solid #f1f5f9}
.acc-body{display:none;padding:1rem;color:var(--muted)}
.acc-head[aria-expanded="true"]{color:var(--accent-2)}
.crisis-note{margin-top:1rem;padding:.8rem;border-radius:8px;background:linear-gradient(90deg,#fff7f7, #fff);border:1px solid #ffebee}

.final-cta{padding:2rem 0;text-align:center}
.site-footer{border-top:1px solid #eef2ff;padding:1.5rem 0;margin-top:2rem}
.footer-grid{display:flex;justify-content:space-between;align-items:flex-start}
.mini-proof{background:#fff;border-radius:8px;padding:.6rem}
.small{font-size:.9rem;color:var(--muted)}

/* Responsive */
@media(max-width:900px){
  .hero-inner{grid-template-columns:1fr;}
  .story-grid{grid-template-columns:1fr}
  .offer-grid,.pricing-grid{grid-template-columns:1fr}
  .proof-gallery{grid-template-columns:1fr}
  .primary-nav{display:none}
  .nav-toggle{display:inline-block}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Year in footer
  document.getElementById('year').textContent = new Date().getFullYear();

  // Mobile nav toggle
  var navToggle = document.querySelector('.nav-toggle');
  var nav = document.querySelector('.primary-nav');
  navToggle && navToggle.addEventListener('click',function(){
    if(nav.style.display==='flex'){nav.style.display='none';navToggle.textContent='☰';}
    else{nav.style.display='flex';nav.style.flexDirection='column';navToggle.textContent='✕';}
  });

  // Accordion behavior for session boundaries
  var accHeads = document.querySelectorAll('.acc-head');
  accHeads.forEach(function(btn){
    btn.addEventListener('click',function(){
      var expanded = this.getAttribute('aria-expanded') === 'true';
      // close all
      accHeads.forEach(function(b){b.setAttribute('aria-expanded','false');b.nextElementSibling.style.display='none';});
      if(!expanded){
        this.setAttribute('aria-expanded','true');
        this.nextElementSibling.style.display='block';
        this.nextElementSibling.focus && this.nextElementSibling.focus();
      }
    });
  });

  // Proof Gallery: rotating testimonials + badge tooltips
  var testiEls = Array.from(document.querySelectorAll('.testi'));
  var badges = Array.from(document.querySelectorAll('.badge'));
  var current = 0;
  var interval = 7000;
  var timer = null;

  function showTesti(i){
    testiEls.forEach(function(t){t.classList.remove('active');});
    var chosen = testiEls[i];
    if(chosen){
      chosen.classList.add('active');
      // highlight badges semi-randomly to pair credibility with quote
      badges.forEach(function(b,idx){b.style.opacity = (idx===i%badges.length)?'1':'0.6';});
    }
  }

  function startCycle(){
    timer = setInterval(function(){
      current = (current+1)%testiEls.length; showTesti(current);
    },interval);
  }

  function stopCycle(){ clearInterval(timer); timer = null; }

  document.getElementById('next').addEventListener('click',function(){ stopCycle(); current=(current+1)%testiEls.length; showTesti(current); startCycle(); });
  document.getElementById('prev').addEventListener('click',function(){ stopCycle(); current=(current-1+testiEls.length)%testiEls.length; showTesti(current); startCycle(); });

  // badge tooltips (simple, accessible)
  badges.forEach(function(b){
    b.addEventListener('mouseenter',function(){
      var tip = b.getAttribute('data-tip');
      var tnode = document.createElement('div');
      tnode.className='badge-tip';
      tnode.textContent = tip;
      tnode.style.position='absolute';
      tnode.style.background='#0f172a';
      tnode.style.color='#fff';
      tnode.style.padding='6px 8px';
      tnode.style.borderRadius='6px';
      tnode.style.fontSize='12px';
      tnode.style.transform='translateY(-110%)';
      b.appendChild(tnode);
      b._tipNode = tnode;
    });
    b.addEventListener('mouseleave',function(){ if(b._tipNode){b.removeChild(b._tipNode);b._tipNode=null;} });
  });

  // Initialize
  showTesti(0); startCycle();

  // Accessibility: pause rotation when user focuses into gallery
  var gallery = document.querySelector('.proof-gallery');
  gallery.addEventListener('focusin', stopCycle);
  gallery.addEventListener('focusout', startCycle);

})();"} 
